def chunk(text: str, size: int = 800, overlap: int = 150) -> list[str]:
    """Split on paragraphs, pack up to ~size chars, carry an overlap into the next chunk."""
    chunks, cur = [], ""
    for para in text.split("\n\n"):
        if cur and len(cur) + len(para) > size:
            chunks.append(cur.strip())
            cur = cur[-overlap:]           # keep context across the boundary
        cur += para + "\n\n"
    if cur.strip():
        chunks.append(cur.strip())
    return chunks

